// Private Unix-socket adapter. Scope keys are generated by Rust, never chosen by
// visitors; a scope authorizes only one webkey-derived UI session, not an account.
const fail = (status, message) => Object.assign(new Error(message), { status });
const validScope = value => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
const validWebkey = value => typeof value === 'string' && /^[a-zA-Z0-9_-]{1,256}$/.test(value);
export function createSharedLeases({ inspect, open, keep, close, waitForResponse, account, now = Date.now }) {
  const records = new Map();
  const dispose = async record => {
    record.closed = true;
    record.ended.abort();
    if (records.get(record.scope) === record) records.delete(record.scope);
    if (record.handle) { const handle = record.handle; record.handle = null; await close(handle); }
  };
  const information = async webkey => {
    if (!inspect || !validWebkey(webkey)) throw fail(403, 'Invalid or unavailable sharing link.');
    return inspect(webkey);
  };
  const identity = async token => {
    if (!token) return null;
    try { return await account(token); }
    catch (error) { if (error.status === 401) return null; throw error; }
  };
  const validate = async record => {
    const info = await information(record.webkey);
    if (record.accountToken) {
      const user = await identity(record.accountToken);
      if (!user || user.id !== record.accountId) throw fail(401, 'Your sign-in has ended.');
    } else if (!info.guestsAllowed) throw fail(403, 'This server requires you to sign in and reveal your identity.');
    if (record.closed || record.expires <= now()) throw fail(410, 'Shared session expired.');
  };
  return {
    async inspect(input) {
      const info = await information(input.webkey);
      const user = await identity(input.accountToken);
      return { ...info, accountName: user?.name || '', accountPictureUrl: user?.pictureUrl || '', signedIn: !!user };
    },
    async open(input, signal) {
      if (!validScope(input.scope) || !validWebkey(input.webkey) || typeof input.revealIdentity !== 'boolean') throw fail(400, 'Invalid shared session request.');
      if (records.has(input.scope)) throw fail(409, 'A shared session is already open.');
      const record = {scope:input.scope, webkey:input.webkey, expires:now()+45000, handle:null, closed:false, ended:new AbortController()};
      records.set(input.scope,record);
      try {
        const info = await information(input.webkey);
        if (input.revealIdentity) {
          const user = await identity(input.accountToken);
          if (!user) throw fail(401, 'Sign in before revealing your identity.');
          record.accountId = user.id; record.accountToken = input.accountToken;
        } else if (!info.guestsAllowed) throw fail(403, 'This server requires you to sign in and reveal your identity.');
        if (record.closed || signal.aborted || record.expires <= now()) throw fail(410,'Shared session closed.');
        const result = await open(record.webkey, record.accountId || null);
        record.handle = result.handle;
        await validate(record);
        if (signal.aborted) throw fail(410,'Shared session closed.');
        return result.view;
      } catch (error) { await dispose(record); throw error; }
    },
    async waitForResponse(input, signal) {
      if (!validScope(input.scope)) throw fail(400, 'Invalid shared scope.');
      const record = records.get(input.scope);
      if (!record?.handle) throw fail(410, 'Shared session unavailable.');
      await validate(record);
      const result = await waitForResponse(record.handle, AbortSignal.any([signal, record.ended.signal]));
      await validate(record);
      return result;
    },
    async keep(input) {
      const record = records.get(input.scope);
      if (!record?.handle) throw fail(410, 'Shared session unavailable.');
      try {
        await validate(record);
        await keep(record.handle);
        await validate(record);
        record.expires = now()+45000;
        return {};
      } catch (error) { await dispose(record); throw error; }
    },
    async close(input) {
      if (!validScope(input.scope)) throw fail(400,'Invalid shared scope.');
      const record = records.get(input.scope);
      if (record) await dispose(record);
      return {};
    },
    async sweep() {
      await Promise.all([...records.values()].map(async record => {
        try { await validate(record); } catch { await dispose(record); }
      }));
    },
  };
}
